anypoint-mq:publish.anypoint-mq:body:
#[output application/json
---
{
    correlationId: correlationId,
    flow:          flow.name,
    environment:   p("mule.env"),
    timestamp:     now() as String { format: "yyyy-MM-dd'T'HH:mm:ss.SSSZ" },
    payload:       payload
    // NOTE: Mask PII fields here before publishing to audit queue
    // Example: payload - { "ssn", "creditCardNumber", "password" }
}]
